macro_rules! get_doc_base_urls {
    () => {
        # [doc = " Get the root URL for the documentation of a definition."] # [doc = ""] # [doc = " ```ignore"] # [doc = " https://doc.rust-lang.org/std/iter/trait.Iterator.html#tymethod.next"] # [doc = " ^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = " file:///project/root/target/doc/std/iter/trait.Iterator.html#tymethod.next"] # [doc = " ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = " ```"] fn get_doc_base_urls (db : & RootDatabase , def : Definition , target_dir : Option < & str > , sysroot : Option < & str > ,) -> (Option < Url > , Option < Url >) { let local_doc = target_dir . and_then (| path | Url :: parse (& format ! ("file:///{path}/")) . ok ()) . and_then (| it | it . join ("doc/") . ok ()) ; let system_doc = sysroot . map (| sysroot | format ! ("file:///{sysroot}/share/doc/rust/html/")) . and_then (| it | Url :: parse (& it) . ok ()) ; let krate = def . krate (db) ; let channel = krate . and_then (| krate | db . toolchain_channel (krate . into ())) . unwrap_or (ReleaseChannel :: Nightly) . as_str () ; if let Definition :: BuiltinType (..) = def { let web_link = Url :: parse (& format ! ("https://doc.rust-lang.org/{channel}/core/")) . ok () ; let system_link = system_doc . and_then (| it | it . join ("core/") . ok ()) ; return (web_link , system_link) ; } ; let Some (krate) = krate else { return Default :: default () } ; let Some (display_name) = krate . display_name (db) else { return Default :: default () } ; let (web_base , local_base) = match krate . origin (db) { CrateOrigin :: Lang (origin @ (LangCrateOrigin :: Alloc | LangCrateOrigin :: Core | LangCrateOrigin :: ProcMacro | LangCrateOrigin :: Std | LangCrateOrigin :: Test) ,) => { let system_url = system_doc . and_then (| it | it . join (& format ! ("{origin}")) . ok ()) ; let web_url = format ! ("https://doc.rust-lang.org/{channel}/{origin}") ; (Some (web_url) , system_url) } CrateOrigin :: Lang (_) => return (None , None) , CrateOrigin :: Rustc { name : _ } => { (Some (format ! ("https://doc.rust-lang.org/{channel}/nightly-rustc/")) , None) } CrateOrigin :: Local { repo : _ , name : _ } => { let weblink = krate . get_html_root_url (db) . or_else (| | { let version = krate . version (db) ; Some (format ! ("https://docs.rs/{krate}/{version}/" , krate = display_name , version = version . as_deref () . unwrap_or ("*"))) }) ; (weblink , local_doc) } CrateOrigin :: Library { repo : _ , name } => { let weblink = krate . get_html_root_url (db) . or_else (| | { let version = krate . version (db) ; Some (format ! ("https://docs.rs/{krate}/{version}/" , krate = name , version = version . as_deref () . unwrap_or ("*"))) }) ; (weblink , local_doc) } } ; let web_base = web_base . and_then (| it | Url :: parse (& it) . ok ()) . and_then (| it | it . join (& format ! ("{display_name}/")) . ok ()) ; let local_base = local_base . and_then (| it | it . join (& format ! ("{display_name}/")) . ok ()) ; (web_base , local_base) }
    };
}

get_doc_base_urls!()